export const getUploadUrl = (folderId: number,
    params: UploadParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/folders/${folderId}/files?${stringifiedParams}` : `/api/v1/folders/${folderId}/files`
}

/**
 * PDF만, 50MB 이하(초과 시 413 FILE_TOO_LARGE). consent=true 필수. title 을 비우면 파일 이름(.pdf 제외, 80자까지)을 써요. 응답은 status=processing 이고, 텍스트 추출이 끝나면 ready · failed 로 바뀌어요
 * @summary PDF 업로드 (P-MAT-02, 03)
 */
export const upload = async (folderId: number,
    params: UploadParams,
    uploadBody?: UploadBody, options?: RequestInit): Promise<UploadResponse> => {
    const formData = new FormData();
if(uploadBody?.file !== undefined) {
 formData.append(`file`, uploadBody.file);
 }

  return apiFetch<UploadResponse>(getUploadUrl(folderId,params),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





